,SMS_RECV_FLAG = #{st_sms_recv_flag}
,DEPARTMENT = #{st_department} ,POSITION = #{st_position} ,STATUS = 'R'
,TWO_FACTOR_YN = #{st_two_factor_flag} ,TWO_FACTOR_DATE = SYSDATE
WHERE USER_ID = #{st_user_id} AND COM_CODE = #{st_com_code}

